<script setup>
import {computed,onMounted,ref} from "vue";import {useRouter} from "vue-router";import {NButton,NEmpty,NTag,NDrawer,NDrawerContent,NAlert,useMessage} from "naive-ui";import PageShell from "../components/PageShell.vue";import Panel from "../components/Panel.vue";
import {monitorApi} from "../api.js";import {can} from "../access.js";import {dateText} from "../display.js";import {openSession} from "../navigation.js";
const router=useRouter(),message=useMessage(),summary=ref(null),traces=ref([]),loading=ref(false),error=ref(""),traceError=ref(""),range=ref('24h'),total=ref(0),page=ref(1),detail=ref(null),detailOpen=ref(false),detailLoading=ref(false);const size=20;
const ranges=[{key:'1h',label:'近 1 小时'},{key:'24h',label:'近 24 小时'},{key:'7d',label:'近 7 天'}];
const stats=computed(()=>{const s=summary.value??{},t=s.toolCalls??{};return [{label:'会话总数',value:s.sessions?.total??'—'},{label:'范围内消息',value:s.messages24h??'—'},{label:'工具调用成功 / 总数',value:`${t.ok??0} / ${t.total??0}`},{label:'P95 工具耗时',value:`${Math.round(s.p95Ms??0)} ms`}];});
const status=(s)=>({ok:{label:'正常',type:'success'},running:{label:'运行中',type:'info'},error:{label:'失败',type:'error'}}[s]??{label:s||'未知',type:'default'});
let loadSeq=0;
async function load(reset=false) {
 if(reset) page.value=1;
 const seq=++loadSeq, selectedRange=range.value, selectedPage=page.value;
 loading.value=true;error.value="";traceError.value="";
 const results=await Promise.allSettled([
  monitorApi.summary(selectedRange),
  can('audit.read') ? monitorApi.traces(new URLSearchParams({range:selectedRange,limit:String(size),offset:String((selectedPage-1)*size)}).toString()) : Promise.resolve(null),
 ]);
 if(seq!==loadSeq)return;
 if(results[0].status==='fulfilled')summary.value=results[0].value;
 else {summary.value=null;error.value=results[0].reason.message;}
 if(results[1].status==='fulfilled'&&results[1].value){traces.value=results[1].value.items??[];total.value=results[1].value.total??0;}
 else {traces.value=[];total.value=0;traceError.value=results[1].status==='rejected'?results[1].reason.message:'当前角色可查看统计摘要，无权查看调用链明细';}
 loading.value=false;
}
async function inspect(item){detailOpen.value=true;detail.value=null;detailLoading.value=true;try{detail.value=await monitorApi.trace(item.traceId);}catch(e){message.error(e.message);}finally{detailLoading.value=false;}}
async function visit(id){try{await openSession(router,id);detailOpen.value=false;}catch(e){message.error(e.message);}}
onMounted(()=>load());
</script><template><PageShell title="监控" subtitle="查看执行表现、失败原因与每轮任务的调用链" :loading="loading" :error="error"><template #actions><n-button @click="load()">刷新</n-button></template><div class="toolbar range-bar"><n-button v-for="r in ranges" :key="r.key" :type="range===r.key?'primary':'default'" @click="range=r.key;load(true)">{{r.label}}</n-button><span class="secondary">范围筛选同时作用于调用链和统计；会话总数为全量。</span></div><div class="stat-grid"><div v-for="stat in stats" :key="stat.label" class="stat-card"><div class="stat-label">{{stat.label}}</div><div class="stat-value">{{stat.value}}</div></div></div><Panel title="最近调用链" :meta="`共 ${total} 条`" :padded="false"><n-alert v-if="traceError" type="warning" :bordered="false">{{traceError}}</n-alert><n-empty v-else-if="!traces.length&&!loading" description="这个时间范围内没有调用记录" class="empty-state"/><div v-else class="table-wrap"><table class="data-table trace-table"><thead><tr><th>开始时间</th><th>会话</th><th>模型</th><th>工具调用</th><th>耗时</th><th>状态</th><th>详情</th></tr></thead><tbody><tr v-for="item in traces" :key="item.traceId"><td>{{dateText(item.startedAt)}}</td><td><n-button text type="primary" @click="visit(item.sessionId)">{{item.sessionId}}</n-button></td><td>{{item.model||'—'}}</td><td>{{item.toolCount??0}}</td><td>{{item.ms===null?'进行中':Math.round(item.ms??0)+' ms'}}</td><td><n-tag :type="status(item.status).type">{{status(item.status).label}}</n-tag></td><td><n-button size="small" @click="inspect(item)">查看调用链</n-button></td></tr></tbody></table></div></Panel><div v-if="can('audit.read')" class="pagination"><span>第 {{page}} 页</span><n-button :disabled="page===1||loading" @click="page--;load()">上一页</n-button><n-button :disabled="page*size>=total||loading" @click="page++;load()">下一页</n-button></div><div class="section-grid"><Panel title="技能调用"><p v-for="s in summary?.skills??[]" :key="s.id">{{s.id}} · {{s.calls}} 次</p><n-empty v-if="!summary?.skills?.length" description="暂无技能调用"/></Panel><Panel title="模型调用"><p v-for="m in summary?.model??[]" :key="m.model">{{m.model}} · {{m.calls}} 次 · 平均 {{Math.round(m.avgMs??0)}} ms</p><n-empty v-if="!summary?.model?.length" description="暂无模型调用"/></Panel></div><n-drawer v-model:show="detailOpen" :width="680"><n-drawer-content title="调用链详情" closable><p v-if="detailLoading">正在加载…</p><template v-if="detail"><dl class="detail-grid"><dt>调用链</dt><dd>{{detail.trace.traceId}}</dd><dt>状态</dt><dd>{{status(detail.trace.status).label}}</dd><dt>会话</dt><dd><n-button text @click="visit(detail.trace.sessionId)">{{detail.trace.sessionId}}</n-button></dd></dl><n-alert v-if="detail.trace.error" type="error">{{detail.trace.error}}</n-alert><article v-for="event in detail.events" :key="event.seq" class="event"><b>{{event.seq}} · {{event.kind}} · {{event.name}}</b><p class="hint">{{event.ok===false?'失败':event.ok===true?'成功':'事件'}} · {{event.ms??'—'}} ms</p><details><summary>事件详情</summary><pre class="json-view">{{JSON.stringify(event.payload,null,2)}}</pre></details></article></template></n-drawer-content></n-drawer></PageShell></template><style scoped>.stat-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:20px}.stat-card{background:white;border:1px solid var(--line);border-radius:12px;padding:20px}.stat-label{color:var(--muted)}.stat-value{font-size:26px;font-weight:600;margin-top:10px;overflow-wrap:anywhere}.event{padding:16px 0;border-bottom:1px solid var(--line)}@media(max-width:1100px){.stat-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:480px){.stat-grid{grid-template-columns:minmax(0,1fr)}}</style>
